// ── Responsive hook ─────────────────────────────────────────────────────────
// Returns true when viewport is at the lg breakpoint or wider (1100px).
// Drives layout decisions (hero 2-col vs stacked, avatar/fingerprint
// sizing) inside this component. Replaces the old desktop/mobile parallel
// component split — this component is now the single canonical profile,
// rendering responsively at all viewports.
// useIsDesktop accepts either a string media query (legacy call sites)
// or a ref to an element whose width should be measured. The ref form
// uses ResizeObserver so the profile detects the actual cell it's
// rendering into; with the persistent sidebar in default.hbs taking
// 320px on the right, the profile lives in an ~828px cell on a 1900px
// screen and a window-width probe would incorrectly say "desktop."
function useIsDesktop(refOrQuery, threshold = 1100) {
  const isRef = refOrQuery && typeof refOrQuery === "object" && "current" in refOrQuery;
  const query = !isRef && typeof refOrQuery === "string" ? refOrQuery : "(min-width: 1100px)";

  const [isDesktop, setIsDesktop] = useState(() => {
    if (typeof window === "undefined" || !window.matchMedia) return true;
    return isRef ? true : window.matchMedia(query).matches;
  });

  useEffect(() => {
    if (isRef) {
      const el = refOrQuery.current;
      if (!el || typeof ResizeObserver === "undefined") {
        const apply = () => {
          if (typeof window !== "undefined") setIsDesktop(window.innerWidth >= threshold);
        };
        apply();
        if (typeof window !== "undefined") {
          window.addEventListener("resize", apply);
          return () => window.removeEventListener("resize", apply);
        }
        return;
      }
      const ro = new ResizeObserver((entries) => {
        for (const entry of entries) {
          setIsDesktop(entry.contentRect.width >= threshold);
        }
      });
      ro.observe(el);
      return () => ro.disconnect();
    }
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia(query);
    const handler = (e) => setIsDesktop(e.matches);
    if (mq.addEventListener) {
      mq.addEventListener("change", handler);
      return () => mq.removeEventListener("change", handler);
    }
    mq.addListener(handler);
    return () => mq.removeListener(handler);
  }, [refOrQuery, threshold, isRef, query]);

  return isDesktop;
}
