// Spine-shaped cell on the influences shelf. When a cover image is present
// (Open Library lookup OR direct upload), it fills the cell and the title
// is suppressed; the card list below the shelf carries text. When no cover
// is set, falls back to a colored spine with the title typeset vertically,
// matching the original mock aesthetic. `book.color` is optional and only
// used in the no-cover branch; influences saved through the editor will
// hash a color from the title at write time so legacy spines stay stable.
function BookSpine({ book }) {
  const hasCover = !!book.cover_url;
  const fallbackColor = book.color || hashColor(book.title || '');
  return (
    <div style={{
      flex: 1, minWidth: 36, maxWidth: 56,
      height: 160,
      background: hasCover ? "#1a1612" : `linear-gradient(180deg, ${fallbackColor}, ${fallbackColor}dd)`,
      borderRadius: "2px 2px 1px 1px",
      border: `1px solid rgba(0,0,0,0.15)`,
      boxShadow: "0 2px 6px rgba(28,24,20,0.12), inset -2px 0 4px rgba(0,0,0,0.1)",
      display: "flex", alignItems: hasCover ? "stretch" : "center", justifyContent: "center",
      padding: hasCover ? 0 : "12px 6px",
      cursor: "pointer",
      transition: "transform 0.2s",
      overflow: "hidden",
    }}
    title={book.author ? `${book.title} — ${book.author}` : book.title}
    onMouseEnter={e => e.currentTarget.style.transform = "translateY(-4px)"}
    onMouseLeave={e => e.currentTarget.style.transform = "translateY(0)"}
    >
      {hasCover ? (
        <img
          src={book.cover_url}
          alt={book.title}
          style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }}
        />
      ) : (
        <div style={{
          fontFamily: T.fontDisplay, fontSize: 11, fontWeight: 500,
          color: T.bgWhite, writingMode: "vertical-rl", transform: "rotate(180deg)",
          textAlign: "center", letterSpacing: "0.02em", lineHeight: 1.2,
          textShadow: "0 1px 2px rgba(0,0,0,0.4)",
          whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis",
          maxHeight: 130,
        }}>
          {book.title}
        </div>
      )}
    </div>
  );
}

